mapper.select:
SELECT * FROM service_schedule
WHERE member_id = #{memberId}
AND date = #{date}
ORDER BY time_slot ASC

SELECT ss.* FROM service_schedule ss
INNER JOIN service_member sm ON ss.member_id = sm.id
WHERE ss.service_type = #{serviceType}
AND ss.date = #{date}
AND (ss.store_id = #{storeId} OR (ss.store_id IS NULL AND sm.store_id = #{storeId}))
ORDER BY ss.time_slot ASC

SELECT ss.* FROM service_schedule ss
INNER JOIN service_member sm ON ss.member_id = sm.id
WHERE ss.service_type = #{serviceType}
AND ss.date >= #{startDate}
AND ss.date <= #{endDate}
AND (ss.store_id = #{storeId} OR (ss.store_id IS NULL AND sm.store_id = #{storeId}))
ORDER BY ss.date ASC, ss.time_slot ASC

SELECT * FROM service_schedule
WHERE date = #{date}
AND time_slot = #{timeSlot}
AND status = #{status}
